package be.imgn.it;

import static org.assertj.core.api.Assertions.assertThat;

import org.antlr.v4.runtime.RuntimeMetaData;
import org.junit.jupiter.api.Test;

/**
 * The BOM's antlr4-runtime must match the parent's antlr4-maven-plugin: a parser generated by one version and run by
 * another fails at run time, not at build time.
 */
class AntlrVersionTest {

    @Test
    void runtimeMatchesTheParentsGenerator() {
        assertThat(RuntimeMetaData.VERSION).isEqualTo(System.getProperty("parent.antlr4.version"));
    }
}
